using System.Data.Common;
using FastSql.Metadata;
using FastSql.Providers;
using FastSql.Providers.OracleBase;
using FastSql.Sql;

namespace FastSql.Providers.Dameng;

/// <summary>达梦的驱动槽位（§9.1 的 Oracle 血统那一行）。<b>它今天只覆写一格：<c>CreateCodeFirst</c></b>，
/// 而那一格的理由与"为什么只有这一格"是一件事，所以两段都写在这里而不是拆到别处。
///
/// <para><b>为什么只有 DDL 这一格分岔</b>：自增写法在这一家长成 <c>IDENTITY(1,1)</c> —— 与基类那行
/// <c>GENERATED BY DEFAULT AS IDENTITY</c> 不同形，而与 SQL Server 同形（达梦的语法表大量取自 SQL Server，
/// §9.1 那句"两家在这一点上同形不是巧合"）。读侧、写侧、守卫、引号、分页全部继承：
/// <b>【v0.31】那句"两家同形"今天是三家</b>：第五家发的也是同一串 <c>IDENTITY(1,1)</c>，而它的内核自研、
/// 没有"语法表取自 SQL Server"这条来历 —— 归因只覆盖达梦一家，重数与判据记在 <c>OracleCodeFirst</c>
/// 类注释那条 <c>IdentityClause</c> 的【v0.31】段，这里不抄第二遍。
/// <c>SELECT … ROWNUM …</c>、双引号折大写、<c>'' IS NULL</c>、<c>NUMBER(1)</c> 装布尔、LOB 不能等号比 ——
/// 这几条在达梦的文档里都是同一族的规则，所以它们在代码里也就是同一份实现。</para>
///
/// <para><b>三件已知"可能不该继承"而今天仍然继承着的东西</b>（每一件都要一台活库才判得了，逐条对到 §14）：
/// <list type="bullet">
/// <item><c>VARCHAR2(n CHAR)</c> 的那颗 <c>CHAR</c> 限定词。基类发它是为了不赌会话的 <c>NLS_LENGTH_SEMANTICS</c>
/// 式默认值（§10.4 第三家），而达梦的量纲默认值在建库参数里；它认不认这个限定词<em>未实测</em>。
/// 覆写点在 <see cref="OracleTypes"/> 那颗 <c>virtual</c> 上，今天没有用它 —— 先假定要，等现场否。</item>
/// <item>分页。§4 原稿给这一家写的是"从 Oracle 分支拿 <c>Paging_RowNum</c> 再叠 <c>OffsetFetch</c>"，
/// 而叠 <c>OffsetFetch</c> 意味着换一套发射（不是加一位掩码）。今天只有 ROWNUM 那三层：它慢一点，
/// 但两家的文档都认。等第一次真库跑批看执行计划再决定要不要那一格。</item>
/// <item>参数预算。基类给的是 <see langword="null"/>（<c>StatementEmitter</c> 那份 100 的兜底），
/// 而达梦的驱动上限今天没有可举证的数字 —— 与上一条同一种"先不猜"。</item>
/// </list></para>
///
/// <para><b>本类没有一处经过真库验证</b>：授权实例里没有这一血统的一家（§13.1 第 4 项），
/// 所以这一版交付的是文本层与它的断言，不是连接层。</para></summary>
[FastSqlProvider(DbKind.Dameng)]
public sealed class DamengProvider : OracleProviderBase
{
    /// <summary>清单里的 <c>key</c>。程序集名按厂商文档写成 <c>DmProvider</c>，<b>从未在一台机器上解析成功过</b>
    /// （§13.5 台账），所以清单里那一行刻意不写 <c>factoryType</c> —— 省略它走的是"扫导出类型里第一个
    /// <see cref="DbProviderFactory"/> 子类"那条兜底，比猜一个全名更容易成。</summary>
    public const string DriverKey = "dameng";

    public DamengProvider(DbProviderFactory driverFactory)
        : base(DbKind.Dameng, driverFactory)
    {
    }

    /// <summary>换掉 DDL 的那一颗实例，而不是整条 <see cref="IDbProvider"/> —— §4 那条继承链的意思就是
    /// "子类加或减这一档，不另起一份"。</summary>
    protected override ICodeFirstDialect CreateCodeFirst(OracleTypes types) => new DamengCodeFirst(types);
}

/// <summary>达梦的 DDL：与基类只差自增那一颗写法，所以整个类就一条覆写。
///
/// <para><c>IDENTITY(1,1)</c> 在这里是<em>列定义的一部分</em>而不是约束，位置与 <c>NOT NULL</c> 的先后
/// 按厂商文档的示例写（seed/increment 都在括号里，默认 1/1）。它与 §14 那条"显式写自增值要
/// <c>SET IDENTITY_INSERT ON</c>"是同一颗列的两半：这一格建列，那一格会话开关 ——
/// 后者今天<em>没有</em>被覆写，因为 <see cref="IKeyStrategy.IdentityInsertToggle"/> 在 Core 里没有调用点
/// （写自增列在问到 provider 之前就被 <c>UpdateEngine</c> 拒了），覆写它会得到一颗永不执行的虚函数。</para></summary>
sealed class DamengCodeFirst(OracleTypes types) : OracleCodeFirst(types)
{
    protected override string IdentityClause => " IDENTITY(1,1)";
}
